<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class PageTranslationsSchema extends SchemaDefinition { protected string $table = 'page_translations'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('page_id'); $table->string_50('locale')->index(); $table->string_255('title'); $table->long_text('content')->nullable(); $table->foreign('page_id')->references('id')->on('pages')->onDelete('CASCADE'); $table->unique('page_id', 'locale'); } } 